def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    """Reciprocate based on recipient's last action toward us (like TFT but with default defect if no history)."""
    for entry in reversed(my_history):
        if entry["role"] == "recipient" and entry["partner"] == recipient_id:
            return entry["partner_action"] == "donate"
    return False  # Default defect when no prior interaction
